// Builds the full, flat breakdown of an estimate and serialises it to JSON / CSV.

// Display-only currencies: amounts are never converted, only the unit shown changes
export const CURRENCIES = [
  { code: 'EUR', symbol: '€' },
  { code: 'USD', symbol: '$' },
  { code: 'GBP', symbol: '£' },
  { code: 'CHF', symbol: 'CHF' },
  { code: 'CAD', symbol: 'CA$' },
  { code: 'AUD', symbol: 'A$' },
  { code: 'JPY', symbol: '¥' },
  { code: 'CNY', symbol: 'CN¥' },
  { code: 'SEK', symbol: 'kr' },
  { code: 'PLN', symbol: 'zł' }
];
export const getCurrencySymbol = (code) => {
  const c = CURRENCIES.find((x) => x.code === code);
  return c ? c.symbol : '€';
};

// Shop-rate assumptions (same as the original "recommended price" formula)
export const MACHINE_RATE_PER_HOUR = 0.83; // wear + electricity, €/h
export const DEFAULT_PRICE_PER_KG = 15; // last-resort price/kg when neither the user nor the catalog gave one

// Price per kg actually used (and sent to the API): user input > material preset > global default
export function resolvePricePerKg(settings, material) {
  if (settings.pricePerKg !== '' && settings.pricePerKg != null && Number(settings.pricePerKg) >= 0) {
    return { value: Number(settings.pricePerKg), source: 'user' };
  }
  if (material && Number(material.defaultPricePerKg) > 0) {
    return { value: Number(material.defaultPricePerKg), source: 'material_default' };
  }
  return { value: DEFAULT_PRICE_PER_KG, source: 'default' };
}
const FILAMENT_DIAMETER_MM = 1.75;

const round = (v, digits = 2) => {
  const f = 10 ** digits;
  return Math.round(v * f) / f;
};

// Axis-aligned fit check: true when the (oriented) model exceeds the build volume
export function exceedsBuildVolume(modelDims, bedSize) {
  if (!modelDims || !bedSize) return false;
  return modelDims.x > bedSize[0] + 0.01
    || modelDims.y > bedSize[1] + 0.01
    || modelDims.z > bedSize[2] + 0.01;
}

// True when the oriented model has meaningful overhangs (>= 20 mm² and >= 0.5% of the surface)
export function needsSupport(modelDims) {
  if (!modelDims || !(modelDims.overhangArea > 0)) return false;
  return modelDims.overhangArea >= 20 && modelDims.overhangArea / modelDims.totalArea >= 0.005;
}

export function formatDuration(seconds) {
  if (!seconds || seconds <= 0) return '0s';
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.round(seconds % 60);
  return `${h > 0 ? h + 'h ' : ''}${h > 0 || m > 0 ? m + 'm ' : ''}${s}s`;
}

// `context` is the snapshot taken when the estimate was launched:
// { file, settings, printer, material, modelDims, createdAt }
export function buildEstimateDetails(result, context) {
  const { file, settings = {}, printer, material, modelDims, createdAt } = context;

  const grams = result.total_filament_used_g || 0;
  const seconds = result.estimated_printing_time_seconds || 0;
  const hours = seconds / 3600;

  const density = Number(settings.filamentDensity) > 0
    ? Number(settings.filamentDensity)
    : (material && material.density) || null;
  const { value: pricePerKg, source: priceSource } = resolvePricePerKg(settings, material);

  const volumeCm3 = density ? grams / density : null;
  const lengthM = volumeCm3 != null
    ? (volumeCm3 * 1000) / (Math.PI * (FILAMENT_DIAMETER_MM / 2) ** 2) / 1000
    : null;

  // Backend value when available (its currency is ignored), otherwise the same formula locally
  const apiCost = result.cost && result.cost.material_cost != null ? Number(result.cost.material_cost) : null;
  const materialCost = apiCost != null ? apiCost : grams / 1000 * pricePerKg;
  const rateGiven = settings.machineRate !== '' && settings.machineRate != null && Number(settings.machineRate) >= 0;
  const machineRate = rateGiven ? Number(settings.machineRate) : MACHINE_RATE_PER_HOUR;
  const machineCost = hours * machineRate;
  const rawCost = materialCost + machineCost;

  return {
    generated_at: createdAt,
    model: {
      file_name: file ? file.name : null,
      file_size_bytes: file ? file.size : null,
      size_x_mm: modelDims ? round(modelDims.x, 1) : null,
      size_y_mm: modelDims ? round(modelDims.y, 1) : null,
      size_z_mm: modelDims ? round(modelDims.z, 1) : null,
      rotate_x_deg: Number(settings.rotateX) || 0,
      rotate_y_deg: Number(settings.rotateY) || 0,
      rotate_z_deg: Number(settings.rotateZ) || 0
    },
    printer: {
      id: result.printer || (printer && printer.id) || null,
      name: printer ? printer.displayName : null,
      manufacturer: printer ? printer.manufacturer : null,
      bed_x_mm: printer && printer.bedSize ? printer.bedSize[0] : null,
      bed_y_mm: printer && printer.bedSize ? printer.bedSize[1] : null,
      bed_z_mm: printer && printer.bedSize ? printer.bedSize[2] : null,
      default_speed_mm_s: printer ? printer.defaultSpeed : null,
      default_acceleration_mm_s2: printer ? printer.defaultAcceleration : null,
      fits_build_volume: !exceedsBuildVolume(modelDims, printer && printer.bedSize)
    },
    material: {
      id: result.material || (material && material.id) || null,
      name: material ? material.displayName : null,
      density_g_cm3: density,
      max_volumetric_speed_mm3_s: material ? material.maxVolumetricSpeed : null,
      price_per_kg: round(pricePerKg),
      price_per_kg_source: priceSource
    },
    settings: {
      quality: settings.quality || 'preset default',
      layer_height_mm: Number(settings.layerHeight) > 0 ? Number(settings.layerHeight) : 'preset default',
      infill_percent: settings.infill !== '' && settings.infill != null ? Number(settings.infill) : 'preset default',
      support: settings.support == null ? 'preset default' : Boolean(settings.support),
      speed_mm_s: Number(settings.speed) > 0 ? Number(settings.speed) : 'preset default',
      acceleration_mm_s2: Number(settings.acceleration) > 0 ? Number(settings.acceleration) : 'preset default'
    },
    estimate: {
      print_time_seconds: seconds,
      print_time_hours: round(hours, 3),
      print_time_formatted: formatDuration(seconds),
      filament_weight_g: round(grams),
      filament_volume_cm3: volumeCm3 != null ? round(volumeCm3) : null,
      filament_length_m_1_75mm: lengthM != null ? round(lengthM) : null
    },
    costs: {
      currency: settings.currency || 'EUR',
      material_cost: round(materialCost),
      material_cost_source: apiCost != null ? 'api' : 'computed',
      machine_rate_per_hour: machineRate,
      machine_rate_source: rateGiven ? 'user' : 'default',
      machine_cost: round(machineCost),
      raw_cost: round(rawCost),
      raw_cost_per_gram: grams > 0 ? round(rawCost / grams, 4) : null,
      raw_cost_per_hour: hours > 0 ? round(rawCost / hours) : null
    }
  };
}

const csvCell = (v) => {
  if (v === null || v === undefined) return '';
  const s = String(v);
  return /[",;\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

// One row per value: section,key,value
export function detailsToCsv(details) {
  const rows = [['section', 'key', 'value']];
  Object.entries(details).forEach(([section, content]) => {
    if (content !== null && typeof content === 'object') {
      Object.entries(content).forEach(([key, value]) => rows.push([section, key, value]));
    } else {
      rows.push(['meta', section, content]);
    }
  });
  // BOM so Excel reads UTF-8 correctly
  return '﻿' + rows.map((r) => r.map(csvCell).join(',')).join('\r\n') + '\r\n';
}

export function downloadTextFile(filename, content, mime) {
  const blob = new Blob([content], { type: `${mime};charset=utf-8` });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}
