import React from 'react';
import { useTranslation } from 'react-i18next';
import { AlertTriangle } from 'lucide-react';

const fmt = (d) => `${Math.round(d.x)} × ${Math.round(d.y)} × ${Math.round(d.z)} mm`;

export default function OversizeModal({ show, modelDims, printer, onCancel, onConfirm }) {
  const { t } = useTranslation();
  if (!show || !modelDims || !printer) return null;

  const axes = ['x', 'y', 'z'].filter((a, i) => modelDims[a] > printer.bedSize[i] + 0.01);

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-900/40 backdrop-blur-xs flex items-center justify-center p-4">
      <div
        role="alertdialog"
        aria-modal="true"
        className="bg-white rounded-2xl shadow-xl border border-slate-200 w-full max-w-md overflow-hidden"
      >
        <div className="flex items-start space-x-3 px-5 py-4">
          <div className="w-9 h-9 shrink-0 rounded-xl bg-rose-100 text-rose-600 flex items-center justify-center">
            <AlertTriangle className="w-5 h-5" />
          </div>
          <div>
            <h2 className="text-sm font-bold text-slate-900">{t('oversizeTitle')}</h2>
            <p className="text-xs text-slate-600 mt-1">
              {t('oversizeMessage', { printer: printer.displayName })}
            </p>
            <dl className="mt-3 text-xs font-mono space-y-1">
              <div className="flex justify-between gap-4">
                <dt className="text-slate-500">{t('oversizeModel')}</dt>
                <dd className="font-semibold text-rose-600">{fmt(modelDims)}</dd>
              </div>
              <div className="flex justify-between gap-4">
                <dt className="text-slate-500">{t('oversizeBed')}</dt>
                <dd className="font-semibold text-slate-800">{fmt({ x: printer.bedSize[0], y: printer.bedSize[1], z: printer.bedSize[2] })}</dd>
              </div>
              <div className="flex justify-between gap-4">
                <dt className="text-slate-500">{t('oversizeAxes')}</dt>
                <dd className="font-semibold text-slate-800">{axes.map((a) => a.toUpperCase()).join(', ')}</dd>
              </div>
            </dl>
            <p className="text-[11px] text-slate-500 mt-3">{t('oversizeHint')}</p>
          </div>
        </div>
        <div className="flex justify-end gap-2 px-5 py-3 bg-slate-50 border-t border-slate-100">
          <button
            type="button"
            autoFocus
            onClick={onCancel}
            className="px-3 py-1.5 rounded-lg text-xs font-semibold border border-slate-200 bg-white hover:bg-slate-50 text-slate-700"
          >
            {t('oversizeCancel')}
          </button>
          <button
            type="button"
            onClick={onConfirm}
            className="px-3 py-1.5 rounded-lg text-xs font-semibold bg-rose-600 hover:bg-rose-700 text-white"
          >
            {t('oversizeContinue')}
          </button>
        </div>
      </div>
    </div>
  );
}
