import React, { useState, useRef, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { Globe, Key, KeyRound, Sparkles, Check, ChevronDown } from 'lucide-react';

const LANGUAGES = [
  { code: 'en', label: 'English', short: 'EN' },
  { code: 'fr', label: 'Français', short: 'FR' },
  { code: 'es', label: 'Español', short: 'ES' },
  { code: 'de', label: 'Deutsch', short: 'DE' },
  { code: 'it', label: 'Italiano', short: 'IT' },
];

export default function Header({
  isHosted,
  hasApiKey,
  onOpenApiKeyModal,
  onOpenWizard
}) {
  const { t, i18n } = useTranslation();
  const [langMenuOpen, setLangMenuOpen] = useState(false);
  const langRef = useRef(null);

  const currentLangCode = (i18n.language || 'en').split('-')[0];
  const currentLang = LANGUAGES.find((l) => l.code === currentLangCode) || LANGUAGES[0];

  const handleLanguageChange = (code) => {
    i18n.changeLanguage(code);
    try {
      localStorage.setItem('slicer_language', code);
    } catch (e) {}
    setLangMenuOpen(false);
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (langRef.current && !langRef.current.contains(event.target)) {
        setLangMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <header className="bg-white border-b border-slate-200 sticky top-0 z-40 shadow-2xs">
      <div className="w-full px-4 sm:px-6 h-14 flex items-center justify-between">
        {/* Brand & App Title (Clean, no "orca slicer studio") */}
        <div className="flex items-center space-x-3">
          <div className="w-9 h-9 rounded-lg bg-gradient-to-tr from-sky-500 to-emerald-500 p-0.5 shadow-xs flex items-center justify-center">
            <div className="w-full h-full bg-white rounded-[7px] flex items-center justify-center">
              <img src={`${process.env.PUBLIC_URL}/logo192.png`} alt="Logo" className="w-5 h-5 object-contain" />
            </div>
          </div>
          <div>
            <h1 className="text-sm sm:text-base font-bold text-slate-900 leading-none">
              {t('appName')}
            </h1>
            <p className="text-[11px] text-slate-500 hidden sm:block mt-0.5">
              {t('appSubtitle')}
            </p>
          </div>
        </div>

        {/* Right Tools Bar: Wizard, API Key, Compact Language Dropdown */}
        <div className="flex items-center space-x-2 sm:space-x-2.5">
          {/* Quick Setup / Replay Wizard */}
          <button
            type="button"
            onClick={onOpenWizard}
            className="inline-flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg text-xs font-medium text-slate-700 bg-slate-100 hover:bg-slate-200/80 border border-slate-200 transition-colors shadow-2xs"
            title={t('quickSetup')}
          >
            <Sparkles className="w-3.5 h-3.5 text-sky-600" />
            <span className="hidden md:inline">{t('quickSetup')}</span>
          </button>

          {/* API Key Status & Config Button (Hidden in ?hosted mode) */}
          {!isHosted && (
            <button
              type="button"
              onClick={onOpenApiKeyModal}
              className={`inline-flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg text-xs font-medium transition-colors border shadow-2xs ${
                hasApiKey
                  ? 'bg-emerald-50 text-emerald-700 border-emerald-300 hover:bg-emerald-100'
                  : 'bg-amber-50 text-amber-700 border-amber-300 hover:bg-amber-100'
              }`}
              title={t('apiKeyTip')}
            >
              {hasApiKey ? (
                <KeyRound className="w-3.5 h-3.5 text-emerald-600" />
              ) : (
                <Key className="w-3.5 h-3.5 text-amber-600" />
              )}
              <span className="hidden sm:inline">
                {hasApiKey ? t('apiKeyConfigured') : t('apiKeyMissing')}
              </span>
              <span
                className={`w-1.5 h-1.5 rounded-full ${
                  hasApiKey ? 'bg-emerald-500' : 'bg-amber-500 animate-pulse'
                }`}
              />
            </button>
          )}

          {/* Compact Language Selector Dropdown */}
          <div className="relative" ref={langRef}>
            <button
              type="button"
              onClick={() => setLangMenuOpen(!langMenuOpen)}
              className="inline-flex items-center space-x-1 px-2 py-1.5 rounded-lg text-xs font-semibold text-slate-700 bg-slate-100 hover:bg-slate-200 border border-slate-200 shadow-2xs"
            >
              <Globe className="w-3.5 h-3.5 text-slate-500" />
              <span>{currentLang.short}</span>
              <ChevronDown className="w-3 h-3 text-slate-400" />
            </button>

            {langMenuOpen && (
              <div className="absolute right-0 mt-1 w-32 bg-white rounded-xl shadow-lg border border-slate-200 py-1 z-50 animate-in fade-in zoom-in-95 duration-100">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    type="button"
                    onClick={() => handleLanguageChange(lang.code)}
                    className="w-full px-3 py-1.5 text-left text-xs font-medium text-slate-700 hover:bg-slate-50 flex items-center justify-between"
                  >
                    <span>{lang.label}</span>
                    {currentLangCode === lang.code && (
                      <Check className="w-3.5 h-3.5 text-primary-600" />
                    )}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </header>
  );
}
