import React from 'react';
import { useTranslation } from 'react-i18next';
import { Clock, Weight, Euro, RotateCw, CheckCircle2, FileJson, FileSpreadsheet } from 'lucide-react';
import { getPrinterCoverUrl, getMaterialSpoolUrl, MATERIAL_DATA } from '../data/printerVisuals';
import {
  buildEstimateDetails,
  detailsToCsv,
  downloadTextFile,
  formatDuration,
  getCurrencySymbol
} from '../services/estimateDetails';

const SECTIONS = ['model', 'printer', 'material', 'settings', 'estimate', 'costs'];

const formatValue = (key, value, t, sym) => {
  if (value === null || value === undefined) return '—';
  if (typeof value === 'boolean') return value ? t('yes') : t('no');
  if (value === 'preset default') return t('presetDefault');
  if (typeof value !== 'number') return String(value);
  if (key === 'price_per_kg' || key.endsWith('_cost') || key.endsWith('_hour') || key === 'raw_cost') {
    return `${value.toFixed(2)} ${sym}`;
  }
  if (key.endsWith('_per_gram')) return `${value.toFixed(4)} ${sym}/g`;
  return String(value);
};

export default function EstimateResultCard({
  result,
  context,
  onRecalculate,
  isSimple
}) {
  const { t } = useTranslation();

  if (!result) return null;

  const { printer: selectedPrinter, settings } = context;
  const selectedMaterial = settings.materialId;
  const sym = getCurrencySymbol(settings.currency);
  const details = buildEstimateDetails(result, context);
  const { estimate, costs } = details;

  const grams = estimate.filament_weight_g;
  const timeSeconds = estimate.print_time_seconds;

  const baseName = (context.file ? context.file.name.replace(/\.[^.]+$/, '') : 'estimate') + '-estimate';
  const exportJson = () => downloadTextFile(`${baseName}.json`, JSON.stringify(details, null, 2), 'application/json');
  const exportCsv = () => downloadTextFile(`${baseName}.csv`, detailsToCsv(details), 'text/csv');

  const matMeta = MATERIAL_DATA[selectedMaterial] || MATERIAL_DATA.pla;

  return (
    <div className="studio-card p-4 sm:p-5 border-2 border-emerald-500/40 bg-gradient-to-b from-emerald-50/20 to-white shadow-md mb-4 animate-in fade-in zoom-in-95 duration-150">
      {/* Header */}
      <div className="flex items-center justify-between pb-3 mb-3 border-b border-emerald-100">
        <div className="flex items-center space-x-2">
          <div className="w-7 h-7 rounded-lg bg-emerald-100 text-emerald-700 flex items-center justify-center">
            <CheckCircle2 className="w-4 h-4 text-emerald-700" />
          </div>
          <div>
            <h2 className="text-sm sm:text-base font-bold text-slate-900 leading-tight">
              {t('estimateResults')}
            </h2>
            <span className="text-[11px] text-slate-500">
              {t('slicedWith')}
            </span>
          </div>
        </div>

        <button
          type="button"
          onClick={onRecalculate}
          className="inline-flex items-center space-x-1 text-xs font-semibold px-2.5 py-1.5 rounded-lg border border-slate-200 bg-white hover:bg-slate-50 text-slate-700 shadow-2xs"
        >
          <RotateCw className="w-3 h-3" />
          <span>{t('recalculate')}</span>
        </button>
      </div>

      {/* Primary Metrics Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5 mb-3">
        {/* Print Time */}
        <div className="p-3 rounded-xl bg-white border border-slate-200/90 shadow-2xs">
          <div className="flex items-center space-x-1.5 text-slate-400 mb-1">
            <Clock className="w-3.5 h-3.5 text-slate-500" />
            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">
              {t('totalPrintTime')}
            </span>
          </div>
          <span className="text-xl sm:text-2xl font-extrabold font-mono text-slate-900 block">
            {formatDuration(timeSeconds)}
          </span>
        </div>

        {/* Filament Used */}
        <div className="p-3 rounded-xl bg-white border border-slate-200/90 shadow-2xs">
          <div className="flex items-center space-x-1.5 text-slate-400 mb-1">
            <Weight className="w-3.5 h-3.5 text-emerald-600" />
            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">
              {t('filamentUsed')}
            </span>
          </div>
          <span className="text-xl sm:text-2xl font-extrabold font-mono text-emerald-600 block">
            {grams} g
          </span>
        </div>

        {/* Raw cost */}
        <div className="p-3 rounded-xl bg-white border border-slate-200/90 shadow-2xs">
          <div className="flex items-center space-x-1.5 text-slate-400 mb-1">
            <Euro className="w-3.5 h-3.5 text-primary-600" />
            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">
              {t('det.raw_cost')}
            </span>
          </div>
          <span className="text-xl sm:text-2xl font-extrabold font-mono text-primary-600 block">
            {costs.raw_cost.toFixed(2)} {sym}
          </span>
          <span className="text-[11px] text-slate-500 font-mono block mt-0.5">
            {t('det.material_cost')} {costs.material_cost.toFixed(2)} {sym} · {t('det.machine_cost_short')} {costs.machine_cost.toFixed(2)} {sym}
          </span>
        </div>
      </div>

      {/* Recap Metadata */}
      <div className="p-2.5 rounded-xl bg-slate-50 border border-slate-200/80 flex items-center justify-between flex-wrap gap-2 text-xs">
        <div className="flex items-center space-x-3">
          <div className="flex items-center space-x-1.5">
            <img
              src={getPrinterCoverUrl(selectedPrinter ? selectedPrinter.id : '')}
              alt=""
              className="w-5 h-5 object-contain rounded"
            />
            <span className="font-semibold text-slate-800">
              {selectedPrinter ? selectedPrinter.displayName : t('printerFallback')}
            </span>
          </div>
          <span className="text-slate-300">|</span>
          <div className="flex items-center space-x-1.5">
            <img
              src={getMaterialSpoolUrl(selectedMaterial)}
              alt=""
              className="w-4 h-4 object-contain"
            />
            <span className="font-semibold text-slate-800">
              {matMeta.name} ({matMeta.density}g/cm³)
            </span>
          </div>
        </div>

      </div>

      {/* Full breakdown */}
      <div className="mt-3 grid grid-cols-1 md:grid-cols-2 gap-2.5">
        {SECTIONS.map((section) => (
          <div key={section} className="rounded-xl border border-slate-200/90 bg-white overflow-hidden">
            <h3 className="px-3 py-1.5 text-[10px] font-bold uppercase tracking-wide text-slate-500 bg-slate-50 border-b border-slate-100">
              {t(`detSection.${section}`)}
            </h3>
            <dl className="divide-y divide-slate-100 text-xs">
              {Object.entries(details[section]).map(([key, value]) => (
                <div key={key} className="flex items-baseline justify-between gap-3 px-3 py-1">
                  <dt className="text-slate-500">{t(`det.${key}`, { defaultValue: key, cur: sym })}</dt>
                  <dd className={`font-mono text-right text-slate-800 ${
                    key === 'raw_cost' ? 'font-bold' : ''
                  } ${key === 'fits_build_volume' && value === false ? 'font-bold text-rose-600' : ''}`}>
                    {formatValue(key, value, t, sym)}
                  </dd>
                </div>
              ))}
            </dl>
          </div>
        ))}
      </div>

      {/* Export */}
      <div className="mt-3 flex items-center justify-end gap-2">
        <span className="text-[11px] font-semibold text-slate-500 mr-1">{t('exportDetails')}</span>
        <button
          type="button"
          onClick={exportJson}
          className="inline-flex items-center space-x-1 text-xs font-semibold px-2.5 py-1.5 rounded-lg border border-slate-200 bg-white hover:bg-slate-50 text-slate-700 shadow-2xs"
        >
          <FileJson className="w-3.5 h-3.5" />
          <span>JSON</span>
        </button>
        <button
          type="button"
          onClick={exportCsv}
          className="inline-flex items-center space-x-1 text-xs font-semibold px-2.5 py-1.5 rounded-lg border border-slate-200 bg-white hover:bg-slate-50 text-slate-700 shadow-2xs"
        >
          <FileSpreadsheet className="w-3.5 h-3.5" />
          <span>CSV</span>
        </button>
      </div>

      {/* Simple Kofi flow */}
      {isSimple && (
        <div className="mt-3 pt-2.5 border-t border-slate-100">
          <a
            href="https://ko-fi.com/s/0aed439a68"
            target="_blank"
            rel="noreferrer"
            className="w-full py-2.5 px-4 rounded-xl font-bold text-xs bg-amber-400 hover:bg-amber-500 text-slate-900 flex items-center justify-center space-x-2 shadow-xs transition-colors"
          >
            <img src={`${process.env.PUBLIC_URL}/kofi.png`} alt="ko-fi" className="w-4 h-4 object-contain" />
            <span>{t('orderSample')}</span>
          </a>
        </div>
      )}
    </div>
  );
}
