export const getBrandMeta = (mfg) => {
  return BRAND_CONFIG[mfg] || {
    color: '#64748b',
    bg: '#f8fafc',
    text: '#334155',
    border: '#cbd5e1'
  };
};

export const getPrinterCoverUrl = (printerId) => {
  if (!printerId) return `${PUBLIC}/images/printers/creality_ender3.png`;
  return `${PUBLIC}/images/printers/${printerId}.png`;
};

export const getMaterialSpoolUrl = (materialId) => {
  if (!materialId) return `${PUBLIC}/images/materials/pla.svg`;
  return `${PUBLIC}/images/materials/${materialId.toLowerCase()}.svg`;
};

