import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Sliders, ChevronDown, ChevronUp, RotateCcw } from 'lucide-react';
import { LayerHeightIcon } from './LayerHeightIcon';

export default function QualityAndOptions({
  selectedPrinter,
  quality,
  onChangeQuality,
  layerHeight,
  onChangeLayerHeight,
  infill,
  onChangeInfill,
  support,
  onChangeSupport,
  speed,
  onChangeSpeed,
  acceleration,
  onChangeAcceleration,
  onReset,
  disabled
}) {
  const { t } = useTranslation();
  const [showAdvanced, setShowAdvanced] = useState(false);

  const baseSpeed = selectedPrinter ? selectedPrinter.defaultSpeed : 100;
  const baseAccel = selectedPrinter ? selectedPrinter.defaultAcceleration : 5000;

  const isDefault =
    !quality && !layerHeight && !infill && (support === null || support === undefined) && !speed && !acceleration;

  const qualityOptions = [
    { id: '', level: 'auto', label: t('qDefault'), desc: t('qDefaultDesc'), height: t('qAuto') },
    { id: 'draft', level: 'draft', label: t('qDraft'), desc: t('qDraftDesc'), height: '0.28 mm' },
    { id: 'normal', level: 'normal', label: t('qNormal'), desc: t('qNormalDesc'), height: '0.20 mm' },
    { id: 'precision', level: 'precision', label: t('qFine'), desc: t('qFineDesc'), height: '0.16 mm' },
  ];

  return (
    <div className="studio-card p-4 mb-3.5">
      {/* Header */}
      <div className="flex items-center justify-between mb-2.5">
        <div className="flex items-center space-x-2">
          <Sliders className="w-4 h-4 text-slate-700" />
          <h2 className="text-xs sm:text-sm font-bold text-slate-900 tracking-tight">
            {t('options')}
          </h2>
        </div>
        <div className="flex items-center space-x-3">
          <button
            type="button"
            onClick={onReset}
            disabled={disabled || isDefault}
            className="inline-flex items-center space-x-1 text-xs font-semibold text-slate-500 hover:text-slate-800 hover:underline disabled:opacity-40 disabled:no-underline disabled:cursor-not-allowed"
          >
            <RotateCcw className="w-3 h-3" />
            <span>{t('resetOptions')}</span>
          </button>
          <button
            type="button"
            onClick={() => setShowAdvanced(!showAdvanced)}
            className="inline-flex items-center space-x-1 text-xs font-semibold text-primary-600 hover:text-primary-700 hover:underline"
          >
            <span>{showAdvanced ? t('viewSimple') : t('viewAdvanced')}</span>
            {showAdvanced ? <ChevronUp className="w-3.5 h-3.5" /> : <ChevronDown className="w-3.5 h-3.5" />}
          </button>
        </div>
      </div>

      {/* Quality Pills with Layer Height Icons */}
      <div className="mb-2.5">
        <label className="text-[11px] font-semibold text-slate-700 block mb-1.5">
          {t('printProfile')}
        </label>
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-1.5">
          {qualityOptions.map((q) => {
            const isSelected = quality === q.id;
            return (
              <button
                key={q.id}
                type="button"
                onClick={() => !disabled && onChangeQuality(q.id)}
                disabled={disabled}
                className={`p-2 rounded-xl border text-left transition-all flex flex-col justify-between ${
                  isSelected
                    ? 'bg-primary-50/70 border-primary-500 ring-2 ring-primary-500/20 shadow-xs'
                    : 'bg-white border-slate-200 hover:border-slate-300'
                }`}
              >
                <div className="flex items-center justify-between mb-1.5">
                  <div className="w-7 h-7 rounded-lg bg-slate-100 flex items-center justify-center">
                    <LayerHeightIcon level={q.level} className="w-4 h-4" />
                  </div>
                  <span className="text-[10px] font-mono text-slate-400 font-semibold">{q.height}</span>
                </div>
                <div>
                  <span className="text-xs font-bold text-slate-800 block">{q.label}</span>
                  <span className="text-[10px] text-slate-500 block truncate">{q.desc}</span>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* Main Parameters: Infill & Supports */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 p-2.5 rounded-xl bg-slate-50 border border-slate-200/80 mb-2">
        {/* Infill Density */}
        <div>
          <div className="flex items-center justify-between mb-1">
            <span className="text-[11px] font-semibold text-slate-700">{t('infill')}</span>
            <span className="text-[11px] font-mono font-bold text-primary-600">
              {infill !== '' ? `${infill}%` : t('infillDefault', { value: 20 })}
            </span>
          </div>
          <input
            type="range"
            min="0"
            max="100"
            step="5"
            value={infill !== '' ? infill : 20}
            onChange={(e) => onChangeInfill(Number(e.target.value))}
            disabled={disabled}
            className="w-full h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer"
          />
        </div>

        {/* Supports Toggle */}
        <div className="flex items-center justify-between sm:pl-3 sm:border-l sm:border-slate-200">
          <div>
            <span className="text-[11px] font-semibold text-slate-700 block">{t('supports')}</span>
            <span className="text-[10px] text-slate-500 block">
              {support !== false ? t('supportsAuto') : t('supportsNone')}
            </span>
          </div>
          <label className="relative inline-flex items-center cursor-pointer">
            <input
              type="checkbox"
              checked={support !== false}
              onChange={(e) => onChangeSupport(e.target.checked)}
              disabled={disabled}
              className="sr-only peer"
            />
            <div className="w-9 h-5 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-primary-600"></div>
          </label>
        </div>
      </div>

      {/* Advanced Overrides Drawer */}
      {showAdvanced && (
        <div className="p-2.5 rounded-xl bg-slate-100/70 border border-slate-200 mb-1">
          <div className="flex items-center justify-between mb-2">
            <span className="text-[11px] font-bold text-slate-800">
              {t('hardwareOverrides')}
            </span>
            <span className="text-[10px] text-slate-500">
              {t('overridesHint')}
            </span>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
            <div>
              <label className="text-[10px] font-semibold text-slate-600 block mb-1">
                {t('printSpeedMm')}
              </label>
              <input
                type="number"
                min="15"
                max="500"
                step="5"
                placeholder={t('nativeValue', { value: baseSpeed })}
                value={speed}
                onChange={(e) => onChangeSpeed(e.target.value)}
                disabled={disabled}
                className="w-full px-2 py-1 text-xs rounded-md border border-slate-200 bg-white placeholder-slate-400 focus:outline-none focus:ring-1 focus:ring-primary-500"
              />
            </div>

            <div>
              <label className="text-[10px] font-semibold text-slate-600 block mb-1">
                {t('accelerationMm')}
              </label>
              <input
                type="number"
                min="100"
                max="30000"
                step="100"
                placeholder={t('nativeValue', { value: baseAccel })}
                value={acceleration}
                onChange={(e) => onChangeAcceleration(e.target.value)}
                disabled={disabled}
                className="w-full px-2 py-1 text-xs rounded-md border border-slate-200 bg-white placeholder-slate-400 focus:outline-none focus:ring-1 focus:ring-primary-500"
              />
            </div>

            <div>
              <label className="text-[10px] font-semibold text-slate-600 block mb-1">
                {t('layerHeightMm')}
              </label>
              <input
                type="number"
                min="0.08"
                max="0.40"
                step="0.02"
                placeholder={t('nativeValue', { value: '0.20' })}
                value={layerHeight}
                onChange={(e) => onChangeLayerHeight(e.target.value)}
                disabled={disabled}
                className="w-full px-2 py-1 text-xs rounded-md border border-slate-200 bg-white placeholder-slate-400 focus:outline-none focus:ring-1 focus:ring-primary-500"
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
