import React, { useState, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { Printer, Search } from 'lucide-react';
import { getPrinterCoverUrl, getBrandMeta } from '../data/printerVisuals';

export default function PrinterSelector({
  printers = [],
  selectedPrinterId,
  onSelectPrinter,
  disabled
}) {
  const { t } = useTranslation();
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedBrand, setSelectedBrand] = useState('ALL');

  const brands = useMemo(() => {
    const list = ['ALL'];
    printers.forEach((p) => {
      if (p.manufacturer && !list.includes(p.manufacturer)) {
        list.push(p.manufacturer);
      }
    });
    return list;
  }, [printers]);

  const filteredPrinters = useMemo(() => {
    return printers.filter((p) => {
      const matchBrand = selectedBrand === 'ALL' || p.manufacturer === selectedBrand;
      const matchSearch =
        searchTerm === '' ||
        p.displayName.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.id.toLowerCase().includes(searchTerm.toLowerCase());
      return matchBrand && matchSearch;
    });
  }, [printers, selectedBrand, searchTerm]);

  const activePrinter = printers.find((p) => p.id === selectedPrinterId) || printers[0];
  const brandMeta = activePrinter ? getBrandMeta(activePrinter.manufacturer) : getBrandMeta('');

  return (
    <div className="studio-card p-4 mb-3.5">
      {/* Header */}
      <div className="flex items-center justify-between mb-2.5">
        <div className="flex items-center space-x-2">
          <Printer className="w-4 h-4 text-slate-700" />
          <h2 className="text-xs sm:text-sm font-bold text-slate-900 tracking-tight">
            {t('printerSettings')}
          </h2>
        </div>
        {activePrinter && (
          <span className="text-[11px] font-mono font-medium text-slate-500 bg-slate-100 px-2 py-0.5 rounded-md border border-slate-200">
            {activePrinter.bedSize ? `${activePrinter.bedSize[0]}×${activePrinter.bedSize[1]}×${activePrinter.bedSize[2]} mm` : '220×220×250 mm'}
          </span>
        )}
      </div>

      {/* Selected Printer Spotlight Card (Real cover image) */}
      {activePrinter && (
        <div className="flex items-center space-x-3.5 p-2.5 rounded-xl bg-slate-50 border border-slate-200/80 mb-2.5 shadow-2xs">
          <div className="w-16 h-16 sm:w-18 sm:h-18 bg-white rounded-lg border border-slate-200 p-1 flex items-center justify-center shrink-0 shadow-xs overflow-hidden">
            <img
              src={getPrinterCoverUrl(activePrinter.id)}
              alt={activePrinter.displayName}
              className="w-full h-full object-contain"
              onError={(e) => {
                e.target.onerror = null;
                e.target.src = `${process.env.PUBLIC_URL}/images/printers/creality_ender3.png`;
              }}
            />
          </div>
          <div className="min-w-0 flex-1">
            <div className="flex items-center space-x-2">
              <span
                className="px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wide"
                style={{ backgroundColor: brandMeta.bg, color: brandMeta.text, border: `1px solid ${brandMeta.border}` }}
              >
                {activePrinter.manufacturer}
              </span>
            </div>
            <h3 className="text-xs sm:text-sm font-bold text-slate-900 truncate mt-0.5">
              {activePrinter.displayName}
            </h3>
            <div className="flex flex-wrap gap-x-3 gap-y-0.5 mt-0.5 text-[11px] text-slate-500">
              <span>{t('speedShort')}: <strong className="text-slate-800 font-medium">{activePrinter.defaultSpeed} mm/s</strong></span>
              <span>{t('accelShort')}: <strong className="text-slate-800 font-medium">{activePrinter.defaultAcceleration} mm/s²</strong></span>
            </div>
          </div>
        </div>
      )}

      {/* Filter and Search Bar */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 mb-2.5">
        <div className="relative flex items-center">
          <Search className="w-3.5 h-3.5 text-slate-400 absolute left-2.5 pointer-events-none" />
          <input
            type="text"
            className="w-full pl-8 pr-3 py-1.5 text-xs rounded-lg border border-slate-200 bg-white placeholder-slate-400 focus:outline-none focus:ring-1 focus:ring-primary-500"
            placeholder={t('searchPrinters')}
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            disabled={disabled}
          />
        </div>
        <select
          className="w-full px-2.5 py-1.5 text-xs rounded-lg border border-slate-200 bg-white text-slate-700 focus:outline-none focus:ring-1 focus:ring-primary-500"
          value={selectedBrand}
          onChange={(e) => setSelectedBrand(e.target.value)}
          disabled={disabled}
        >
          {brands.map((b) => (
            <option key={b} value={b}>
              {b === 'ALL' ? t('allManufacturers') : b}
            </option>
          ))}
        </select>
      </div>

      {/* Horizontal Scrollable Carousel with Real Covers */}
      <div className="flex space-x-2 overflow-x-auto pb-1.5 custom-scrollbar">
        {filteredPrinters.map((printer) => {
          const isSelected = printer.id === selectedPrinterId;
          const pBrand = getBrandMeta(printer.manufacturer);
          return (
            <button
              key={printer.id}
              type="button"
              onClick={() => !disabled && onSelectPrinter(printer.id)}
              disabled={disabled}
              className={`w-[115px] shrink-0 text-left p-2 rounded-xl border transition-all flex flex-col justify-between ${
                isSelected
                  ? 'bg-primary-50/70 border-primary-500 ring-2 ring-primary-500/20 shadow-xs'
                  : 'bg-white border-slate-200 hover:border-slate-300 hover:bg-slate-50/50'
              }`}
            >
              <div className="w-full h-16 bg-slate-50 rounded-lg flex items-center justify-center p-1 mb-1.5 border border-slate-100 overflow-hidden">
                <img
                  src={getPrinterCoverUrl(printer.id)}
                  alt={printer.displayName}
                  className="max-h-full max-w-full object-contain"
                  loading="lazy"
                  onError={(e) => {
                    e.target.onerror = null;
                    e.target.src = `${process.env.PUBLIC_URL}/images/printers/creality_ender3.png`;
                  }}
                />
              </div>
              <div className="min-w-0">
                <span
                  className="text-[9px] font-bold block uppercase truncate"
                  style={{ color: pBrand.text }}
                >
                  {printer.manufacturer}
                </span>
                <span className="text-[11px] font-bold text-slate-800 block truncate" title={printer.displayName}>
                  {printer.displayName}
                </span>
                <span className="text-[10px] text-slate-400 font-mono block">
                  {printer.bedSize ? `${printer.bedSize[0]}×${printer.bedSize[1]}` : '220×220'} mm
                </span>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}
